from math import gcd
from typing import List


class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def score(arr):
            if not arr:
                return 0
            g = 0
            l = 1
            for x in arr:
                l = l * x // gcd(l, x)
            return gcd(min(arr), max(arr)) * l

        best = score(nums)
        for i in range(len(nums)):
            best = max(best, score(nums[:i] + nums[i + 1:]))
        return best
